import {creatureArt} from './growth-view.mjs?art=11';
import {CELL,COLS,ROWS,FURNITURE,inventory,openCell} from './garden.mjs?art=11';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const drawings={
 bench:'<path fill="#65472f" d="M5 29h4v13H5zm32 0h4v13h-4z"/><path fill="#a76b3e" d="M3 9h42v19H3zM1 28h46v8H1z"/><path fill="#d9a66a" d="M6 12h36v5H6zm0 9h36v4H6zM4 29h40v4H4z"/>',
 pot:'<path fill="#9b562d" d="M12 28h24v5H12zm3 5h18v11H15z"/><path fill="#db9250" d="M15 30h18v4H15zm3 6h12v5H18z"/><path fill="#3d813e" d="M21 12h6v17h-6zM9 20h12v8H9zm18-5h12v9H27z"/><path fill="#fff9db" d="M18 4h12v5H18zM13 9h22v10H13zm5 10h12v5H18z"/><path fill="#edbd45" d="M21 10h6v8h-6z"/>',
 cushion:'<path fill="#b57b30" d="M8 10h32v5h5v22h-5v5H8v-5H3V15h5z"/><path fill="#f5c45d" d="M9 14h30v5h3v15h-3v4H9v-4H6V19h3z"/><path fill="#ffe3a3" d="M18 21h12v10H18zM12 17h24v3H12z"/>',
 table:'<path fill="#755039" d="M10 25h28v17H10z"/><path fill="#a57145" d="M7 12h34v5h5v15h-5v5H7v-5H2V17h5z"/><path fill="#dfb580" d="M10 14h27v4h6v10h-6v4H10v-4H5V18h5z"/><path fill="none" stroke="#b38457" stroke-width="3" d="M15 18h17v4h5v5H13v-5h5v3h11"/>'
};
export function furnitureArt(kind){return `<svg viewBox="0 0 48 48" aria-hidden="true" shape-rendering="crispEdges">${drawings[kind]||drawings.pot}</svg>`}
function scenery(){return `<svg class="garden-scenery" viewBox="0 0 960 576" aria-hidden="true" shape-rendering="crispEdges"><defs><pattern id="grass" width="96" height="96" patternUnits="userSpaceOnUse"><path fill="#a6cb6d" d="M16 24h4v4h4v-8h4v12H16zM68 76h8v4h-8z"/></pattern><g id="tree"><path fill="#815a39" d="M32 48h16v32H32z"/><path fill="#398653" d="M8 16h16V4h32v12h16v40H56v12H24V56H8z"/><path fill="#69ab58" d="M16 20h16V12h20v12h12v16H44v12H16z"/></g></defs><path fill="#b9d982" d="M0 0h960v576H0z"/><path fill="url(#grass)" d="M0 0h960v576H0z"/><path fill="#84b7a0" d="M720 48h168v24h24v96h-24v24H720v-24h-24V72h24z"/><path fill="#76c9da" d="M730 60h146v24h24v70h-24v24H730v-24h-22V84h22z"/><path fill="#c2edf0" d="M756 90h24v5h-24zm80 50h30v5h-30z"/><path fill="#5b9752" d="M802 77h24v14h-24z"/>${[0,160,400,640,880].map(x=>`<use href="#tree" x="${x}" y="-28"/>`).join('')}${[0,240,580,880].map(x=>`<use href="#tree" x="${x}" y="500"/>`).join('')}<path stroke="#9b784e" stroke-width="8" d="M90 30h70m100 0h120m370 0h110M100 544h100m140 0h190m140 0h150"/></svg>`}
export function gardenContent(state,records,placements,selected,loaded,error,page=0,more=false){
 const owned=inventory(state),shown=records.slice(page*20,(page+1)*20),find=state.gardenLastFind;
 return `<div class="section-head"><div><div class="eyebrow">POCKET GARDEN</div><h2>🌿 みんなの庭</h2><p>育ったともだちが集まる、きみだけの庭。</p></div><span class="pill">${records.length}${more?'＋':''}匹のともだち</span></div>${error?`<div class="error" role="alert">${esc(error)} <button data-action="gardenRetry">もう一度読みこむ</button></div>`:''}<p class="garden-help" role="status">${!loaded?'庭を読みこんでいます…':selected?`${esc(FURNITURE[owned[selected]])}を置く場所をタップしてね。`:'庭は指でスクロールできるよ。家具やともだちをタップしてみよう。'}</p><div class="garden-scroll" tabindex="0" aria-label="広い庭。上下左右にスクロールできます"><div class="garden-world ${selected?'garden-editing':''}">${scenery()}${selected&&loaded?Array.from({length:COLS*ROWS},(_,i)=>{const x=i%COLS,y=Math.floor(i/COLS);return openCell(x,y)?`<button class="garden-cell" data-action="gardenPlace" data-id="${x},${y}" style="left:${x*CELL}px;top:${y*CELL}px" aria-label="横${x}、縦${y}に置く"></button>`:''}).join(''):''}${Object.entries(placements).filter(([id,p])=>owned[id]&&openCell(p.x,p.y)).map(([id,p])=>`<button class="garden-furniture ${id===selected?'selected':''}" style="left:${p.x*CELL}px;top:${p.y*CELL}px" data-action="gardenSelect" data-id="${esc(id)}" aria-label="${esc(FURNITURE[owned[id]])}を動かす">${furnitureArt(owned[id])}</button>`).join('')}<div class="garden-pets">${shown.map(r=>`<button class="garden-pet" data-action="gardenPet" data-id="${esc(r.cycleId)}" aria-label="${esc(r.name)}の思い出">${creatureArt(r.characterId,4)}<span class="pet-mood" aria-hidden="true"></span></button>`).join('')}</div></div></div>${loaded&&!records.length?'<div class="notice">最終進化したともだちが、ここに遊びに来るよ。先に家具を置いて、迎える準備をしよう！</div>':''}${records.length>20?`<div class="actions garden-pages"><button data-action="gardenPrev" ${page===0?'disabled':''}>前の仲間</button><span>${page+1} / ${Math.ceil(records.length/20)}</span><button data-action="gardenNext" ${(page+1)*20>=records.length?'disabled':''}>次の仲間</button></div>`:''}${more?'<button data-action="growthMore">もっと仲間を読みこむ</button>':''}<section class="garden-bag"><div class="section-head"><h3>ひろったもの</h3><span class="pill">${Object.keys(owned).length}こ</span></div>${find?`<p>🎁 ともだちが「${esc(FURNITURE[find.kind])}」をみつけたよ！</p>`:''}<div class="garden-inventory">${Object.entries(owned).map(([id,kind])=>`<button data-action="gardenSelect" data-id="${esc(id)}" aria-pressed="${id===selected}" ${!loaded||error?'disabled':''}>${furnitureArt(kind)}<span>${esc(FURNITURE[kind])}</span><small>${placements[id]?'庭にある':'おけるよ'}</small></button>`).join('')}</div>${selected?`<div class="actions"><button data-action="gardenCancel">やめる</button>${placements[selected]?'<button data-action="gardenPack">しまう</button>':''}</div>`:''}<p class="footer-note">はじめの家具は4こ。育った仲間ができたら、おてつだい3回の承認で家具を1こみつけるよ。みつけられる家具は60こまで。何度でも置き直せます。</p></section>`;
}
let previousPositions=new Map();
export function animateGarden(root,placements){
 if(!root)return ()=>{};const pets=[...root.querySelectorAll('.garden-pet')],used=new Set(),blocked=new Set(Object.values(placements).map(p=>`${p.x},${p.y}`));
 const free=(x,y)=>openCell(x,y)&&!blocked.has(`${x},${y}`)&&!used.has(`${x},${y}`);
 const positions=pets.map((pet,i)=>{const old=previousPositions.get(pet.dataset.id);let x=old?.x,y=old?.y;if(!free(x,y)){for(let n=0;n<180;n++){const a=1+(i*4+2+n)%18,b=3+Math.floor((i*4+n)/18)%6;if(free(a,b)){x=a;y=b;break}}}used.add(`${x},${y}`);pet.style.transform=`translate(${x*CELL}px,${y*CELL-24}px)`;return {x,y,rest:0}});
 previousPositions=new Map(pets.map((pet,i)=>[pet.dataset.id,positions[i]]));
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return ()=>{};
 const timer=setInterval(()=>pets.forEach((pet,i)=>{const p=positions[i];pet.classList.remove('garden-stepping','celebrate');if(p.rest>0){p.rest--;return}pet.querySelector('.pet-mood').textContent='';used.delete(`${p.x},${p.y}`);const [dx,dy]=[[1,0],[-1,0],[0,1],[0,-1]][Math.floor(Math.random()*4)];if(free(p.x+dx,p.y+dy)){p.x+=dx;p.y+=dy;pet.classList.add('garden-stepping')}used.add(`${p.x},${p.y}`);pet.style.transform=`translate(${p.x*CELL}px,${p.y*CELL-24}px)`;const near=Object.values(placements).find(f=>Math.abs(f.x-p.x)+Math.abs(f.y-p.y)===1);if(near||Math.random()<.12){p.rest=3;pet.querySelector('.pet-mood').textContent=near?.kind==='cushion'?'Zzz':near?'♪':'…';if(near&&near.kind!=='cushion')pet.classList.add('celebrate')}}),1200);
 return ()=>clearInterval(timer);
}
